// @generated by the slice schematic 1.2.0 from its spec. Edit in place; reshape via the spec and --force.
import { TestBed } from '@angular/core/testing';
import { LoansViewModel } from './loans.view-model';
import { LoanService } from '../loan/loan.service';

describe('LoansViewModel', () => {
  let vm: LoansViewModel;

  beforeEach(() => {
    TestBed.configureTestingModule({ providers: [LoansViewModel] });
    vm = TestBed.inject(LoansViewModel);
  });

  it('lists every record by default', () => {
    expect(vm.filtered().length).toBe(TestBed.inject(LoanService).loans().length);
  });

  it('filters by the search fields', () => {
    const service = TestBed.inject(LoanService);
    const created = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    vm.searchQuery.set('Test reference'.toLowerCase());
    expect(vm.filtered().map((item) => item.id)).toContain(created.id);
    vm.searchQuery.set('no record contains this');
    expect(vm.filtered()).toEqual([]);
  });

  it('narrows the list when the extended filter is on', () => {
    const service = TestBed.inject(LoanService);
    const matching = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: true,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    const other = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    vm.toggleExtendedFilter();
    expect(vm.filtered().every((item) => item.extended)).toBe(true);
    expect(vm.filtered().map((item) => item.id)).toContain(matching.id);
    expect(vm.filtered().map((item) => item.id)).not.toContain(other.id);
  });

  it('creates a record through save when nothing is being edited', () => {
    const service = TestBed.inject(LoanService);
    const before = service.loans().length;
    vm.startCreate();
    vm.save({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    expect(service.loans().length).toBe(before + 1);
    expect(vm.editing()).toBeNull();
  });

  it('removes a record', () => {
    const service = TestBed.inject(LoanService);
    const created = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    vm.remove(created.id);
    expect(service.byId(created.id)).toBeUndefined();
  });

  it('resolves the record being edited once startEdit runs', () => {
    const service = TestBed.inject(LoanService);
    const created = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    expect(vm.editingLoan()).toBeUndefined();
    vm.startEdit(created.id);
    expect(vm.editingLoan()?.id).toBe(created.id);
  });

  it('updates rather than creates when a record is being edited', () => {
    const service = TestBed.inject(LoanService);
    const created = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    const before = service.loans().length;
    vm.startEdit(created.id);
    vm.save({
      reference: 'Changed',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    expect(service.loans().length).toBe(before);
    expect(service.byId(created.id)?.reference).toEqual('Changed');
    expect(vm.editing()).toBeNull();
  });

  it('falls back to a default badge variant for an unlisted status', () => {
    expect(vm.statusVariant('not a listed value')).toBe('secondary');
  });
});
